const TRAINING_CATALOG=MARKET_HISTORY.symbols;
let trainer={symbol:'NVDA',mode:'replay',session:null,result:null};
let trainingLog=[];try{const saved=JSON.parse(localStorage.getItem('longview-training-v1'));if(Array.isArray(saved))trainingLog=saved.slice(-100)}catch{}
function stockRows(symbol){return TRAINING_CATALOG[symbol].rows.filter(r=>symbol!=='IONQ'||r[0]>='2021-10-01')}
function money(x){return x.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2})}
function tradeAt(book,price,action,fee,budget=0){
 let amount=0,units=0,cost=0;
 if(action==='buy'){amount=Math.min(book.cash,budget);units=amount/(price*(1+fee));cost=units*price*fee;book.cash-=amount;book.units+=units;}
 if(action==='sell'){units=book.units*budget;amount=units*price;cost=amount*fee;book.cash+=amount-cost;book.units-=units;}
 book.fees+=cost;if(units>0)book.trades++;return {units,fee:cost};
}
function statsFor(curve,initial){let peak=initial,dd=0;for(const p of curve){peak=Math.max(peak,p[1]);dd=Math.max(dd,(peak-p[1])/peak)}return {end:curve.at(-1)[1],returnPct:(curve.at(-1)[1]/initial-1)*100,mdd:dd*100}}
function simulateHistory(rows,start,end,initial,fee,strategy){
 const book={cash:initial,units:0,fees:0,trades:0},curve=[[rows[start][0],initial]];
 for(let i=start+1;i<=end;i++){
  const price=rows[i][1],prior=rows[i-1][1];
  if(strategy==='hold'&&i===start+1)tradeAt(book,price,'buy',fee,book.cash);
  if(strategy==='dca'&&[0,21,42,63].includes(i-start-1))tradeAt(book,price,'buy',fee,initial/4);
  if(strategy==='sma'){
   const past=rows.slice(i-20,i);const mean=past.length===20?past.reduce((a,r)=>a+r[1],0)/20:null;
   if(mean!==null&&prior>mean&&book.cash>0.000001)tradeAt(book,price,'buy',fee,book.cash);
   else if(mean!==null&&prior<=mean&&book.units>0)tradeAt(book,price,'sell',fee,1);
  }
  curve.push([rows[i][0],book.cash+book.units*price]);
 }
 return {...statsFor(curve,initial),curve,...book};
}
function training(){return head('판단하고, 결과를 확인하는 투자 훈련','과거 차트의 다음 장을 넘기기 전에, 내 판단과 이유를 먼저 남겨 보세요.')+`<div class="note-banner">실제 과거 일별 조정주가 · ${MARKET_HISTORY.asOf}까지의 고정 자료 · 실시간 모의계좌가 아닙니다. 배당·주식분할 조정 가격으로 계산한 학습 시뮬레이션입니다.</div><div class="topic-chips"><button class="chip ${trainer.mode==='replay'?'selected':''}" data-training-mode="replay">과거 시점 훈련</button><button class="chip ${trainer.mode==='backtest'?'selected':''}" data-training-mode="backtest">전략 백테스트</button></div><section class="panel"><div class="two-col"><label class="field">관심 종목 찾기<input id="stockSearch" type="search" placeholder="예: 엔비디아, IONQ, S&P" autocomplete="off"></label><label class="field">종목 선택<select id="trainingSymbol">${stockOptions('')}</select></label></div><p id="stockAvailability" class="note"></p><div class="two-col"><label class="field">시작일 (이날 종가까지 보고 판단)<input id="trainingStart" type="date" value="2023-01-03"></label><label class="field">종료일<input id="trainingEnd" type="date" value="2023-06-30"></label><label class="field">초기 가상 자금 (USD)<input id="trainingCash" type="number" value="10000" min="100" max="100000000"></label><label class="field">편도 거래비용 (%)<input id="trainingFee" type="number" value="0.1" min="0" max="5" step="0.01"></label></div><button class="primary" id="startTraining">${trainer.mode==='replay'?'미래를 가리고 훈련 시작':'세 전략과 VOO 비교하기'}</button><p id="trainingError" class="note" role="alert"></p><p class="note">검색 대상은 수록된 10개 종목입니다. 지원 기간 밖의 날짜는 임의로 대체하지 않습니다. 새로 시작하면 진행 중 결과가 초기화됩니다.</p></section><div id="trainingStage"></div><section class="panel" style="margin-top:22px"><h3>계산 규칙을 먼저 확인하세요</h3><ul class="note"><li>판단한 날의 다음 거래일 조정 종가에 거래한 것으로 가정합니다. 당일 종가를 보고 당일 종가에 매수하지 않습니다.</li><li>가상 단위의 소수점 보유를 허용합니다. 현금 이자 0%, 추가 입금 없음. 거래비용은 매수·매도마다 적용합니다.</li><li>종료 자산은 미매도 보유분을 평가한 값입니다. 최종 청산 비용, 세금, 환율, 실제 호가와 체결 지연은 제외합니다.</li><li>조정주가는 실제 체결가가 아닙니다. 배당을 반영한 총수익 근사치이며 실제 보유 주식 수와 동일하지 않습니다.</li><li>오늘 살아남은 종목을 골라 과거를 보는 선택 편향과 반복 실험의 과적합이 있습니다. 좋은 과거 결과가 미래 수익을 보장하지 않습니다.</li><li>당시 뉴스·재무정보는 재현하지 않습니다. 현재 알고 있는 기업의 미래를 과거 판단에 사용하지 않도록 주의하세요.</li></ul><a class="note" id="trainingSource" target="_blank" rel="noopener noreferrer">과거 가격 출처 · Yahoo Finance ↗</a></section><section class="panel" style="margin-top:22px"><div class="section-title" style="margin:0 0 12px"><h3>나의 훈련 기록</h3><button class="secondary" id="exportTraining">기록 내려받기 ↓</button></div><p class="note">완료한 결과와 판단 이유를 이 브라우저에 최대 100개 저장합니다. 다른 기기와 동기화되지 않습니다.</p><div id="trainingHistory"></div></section>`}
function stockOptions(query){return Object.entries(TRAINING_CATALOG).filter(([s,d])=>(s+' '+d.name).toLowerCase().includes(query.toLowerCase())).map(([s,d])=>`<option value="${s}" ${s===trainer.symbol?'selected':''}>${d.name} · ${s}</option>`).join('')}
function updateAvailability(){const rows=stockRows(trainer.symbol);$('#stockAvailability').textContent=`수록 기간: ${rows[0][0]} ~ ${rows.at(-1)[0]} · ${rows.length.toLocaleString()}거래일`+(trainer.symbol==='IONQ'?' · 합병 전 SPAC 가격은 연습에서 제외했습니다.':'');$('#trainingSource').href=TRAINING_CATALOG[trainer.symbol].source;['trainingStart','trainingEnd'].forEach(id=>{$('#'+id).min=rows[0][0];$('#'+id).max=rows.at(-1)[0]})}
function bindTraining(){
 document.querySelectorAll('[data-training-mode]').forEach(b=>b.onclick=()=>{trainer.mode=b.dataset.trainingMode;trainer.session=null;trainer.result=null;render()});
 $('#stockSearch').oninput=()=>{const html=stockOptions($('#stockSearch').value);$('#trainingSymbol').innerHTML=html||'<option value="">검색 결과 없음</option>';if(html){trainer.symbol=$('#trainingSymbol').value;updateAvailability()}else $('#stockAvailability').textContent='이 종목은 현재 수록되어 있지 않습니다. 10개 수록 종목 중 선택해 주세요.';};
 $('#trainingSymbol').onchange=()=>{if($('#trainingSymbol').value){trainer.symbol=$('#trainingSymbol').value;updateAvailability()}};
 $('#startTraining').onclick=startTraining;$('#exportTraining').onclick=exportTraining;updateAvailability();showTrainingHistory();if(trainer.session)showReplay();if(trainer.result)showBacktest();
}
function trainingConfig(){
 const symbol=$('#trainingSymbol').value;if(!TRAINING_CATALOG[symbol])throw Error('수록된 종목을 선택해 주세요.');
 const startDate=$('#trainingStart').value,endDate=$('#trainingEnd').value;const rows=stockRows(symbol);
 const initial=Number($('#trainingCash').value),feePct=Number($('#trainingFee').value);
 if(!startDate||!endDate||startDate>=endDate)throw Error('시작일보다 뒤의 종료일을 선택해 주세요.');
 if(startDate<rows[0][0]||endDate>rows.at(-1)[0])throw Error('선택한 기간이 수록 기간을 벗어납니다. 기간을 조정해 주세요.');
 if(!Number.isFinite(initial)||initial<100||initial>100000000||$('#trainingFee').value.trim()===''||!Number.isFinite(feePct)||feePct<0||feePct>5)throw Error('가상 자금은 100~100,000,000달러, 비용은 0~5%로 입력해 주세요.');
 const start=rows.findIndex(r=>r[0]>=startDate);let end=rows.findLastIndex(r=>r[0]<=endDate);
 if(start<20||end-start<2)throw Error('시작일 이전 20거래일과 훈련 구간 내 최소 3거래일이 필요합니다. 시작일을 늦추거나 기간을 늘려 주세요.');
 return {symbol,rows,start,end,initial,fee:feePct/100};
}
function startTraining(){try{const cfg=trainingConfig();$('#trainingError').textContent='';trainer.session=null;trainer.result=null;if(trainer.mode==='replay'){trainer.session={...cfg,cursor:cfg.start,book:{cash:cfg.initial,units:0,fees:0,trades:0},curve:[[cfg.rows[cfg.start][0],cfg.initial]],decisions:[],finished:false,saved:false};showReplay()}else{trainer.result={...cfg,strategies:['hold','dca','sma'].map(s=>({name:{hold:'일괄매수 후 보유',dca:'21거래일 간격 4회 분할',sma:'20일 이동평균 전략'}[s],...simulateHistory(cfg.rows,cfg.start,cfg.end,cfg.initial,cfg.fee,s)}))};showBacktest();recordTraining('백테스트',trainer.result,trainer.result.strategies[0],[]);showTrainingHistory()} }catch(e){$('#trainingError').textContent=e.message}}
function trainingChart(series,normalize=false){const colors=['#214f3b','#b67b2f','#4979a5','#976b91'];const values=series.flatMap(s=>s.curve.map(r=>r[1]));let lo=Math.min(...values),hi=Math.max(...values);const margin=(hi-lo)*.1||1;lo-=margin;hi+=margin;const length=Math.max(...series.map(s=>s.curve.length));const points=s=>s.curve.map((r,i)=>`${60+i/Math.max(1,length-1)*730},${190-(r[1]-lo)/(hi-lo)*160}`).join(' ');return `<svg class="chart" viewBox="0 0 850 235" role="img" aria-label="${normalize?'현재까지 공개된 가격 흐름':'기간별 가상 자산 비교'}">${[0,.5,1].map(t=>`<line x1="60" x2="790" y1="${190-t*160}" y2="${190-t*160}" stroke="#dde5da"/><text x="0" y="${194-t*160}">${Math.round(lo+t*(hi-lo)).toLocaleString()}</text>`).join('')}${series.map((s,i)=>`<polyline points="${points(s)}" fill="none" stroke="${colors[i]}" stroke-width="2.2"/>`).join('')}<text x="60" y="220">${series[0].curve[0][0]}</text><text x="710" y="220">${series[0].curve.at(-1)[0]}</text></svg><div class="note">${series.map((s,i)=>`<span style="color:${colors[i]};margin-right:16px">━━ ${esc(s.name)}</span>`).join('')}</div>`}
function showReplay(){const s=trainer.session;if(!s)return;const row=s.rows[s.cursor],visible=s.rows.slice(Math.max(0,s.cursor-59),s.cursor+1),price=row[1],equity=s.book.cash+s.book.units*price;const p20=s.rows.slice(s.cursor-19,s.cursor+1).reduce((a,r)=>a+r[1],0)/20;$('#trainingStage').innerHTML=`<section class="panel" style="margin-top:22px"><span class="tag">${s.symbol} · ${s.finished?'훈련 종료':'이 날짜 이후의 차트는 숨겨져 있습니다'}</span><h2 style="margin:10px 0">${row[0]}의 판단</h2><p class="note">실제 적용 구간 ${s.rows[s.start][0]} ~ ${s.rows[s.end][0]} · ${s.cursor-s.start}/${s.end-s.start}거래일 진행</p><div class="case-metrics"><div><span class="note">현재 평가 자산</span><strong>${money(equity)}</strong></div><div><span class="note">가상 현금</span><strong>${money(s.book.cash)}</strong></div><div><span class="note">주식 노출 비중</span><strong>${(s.book.units*price/equity*100).toFixed(1)}%</strong></div></div>${trainingChart([{name:'조정가격 · USD · 최근 최대 60거래일',curve:visible}],true)}<p class="note">현재 조정가격 ${price.toFixed(2)} · 현재까지 20일 평균 ${p20.toFixed(2)}. 당시 뉴스는 제공하지 않습니다.</p>${s.finished?replayOutcome(s):`<label class="field">지금 판단하는 이유 (5자 이상)<textarea id="decisionReason" maxlength="500" placeholder="예: 추세는 강하지만 급등 후 변동성이 부담돼 현금을 일부 남긴다."></textarea></label><div class="actions"><button class="primary" data-decision="buy">남은 현금의 25% 매수</button><button class="secondary" data-decision="sell">보유분의 25% 매도</button><button class="secondary" data-decision="hold">현재 비중 유지</button></div><p class="note">판단을 누르면 다음 거래일 조정 종가에 거래하고 그 날짜까지 공개합니다. 매수할 현금 또는 매도할 보유분이 없으면 실행할 수 없습니다.</p><p id="decisionError" role="alert" class="note"></p><button class="text-btn" id="finishReplay">남은 기간은 보유하고 최종 결과 공개 →</button>`}</section><section class="panel" style="margin-top:22px"><h3>내 판단 기록</h3>${s.decisions.length?s.decisions.slice().reverse().map(d=>`<div class="decision-entry"><strong>${d.date} · ${d.action}</strong><p class="note">${esc(d.reason)}<br>${d.execution?`가정 체결일 ${d.execution} · 비용 ${money(d.fee)}`:'남은 기간 추가 거래 없음'}</p></div>`).join(''):'<p class="note">아직 판단하지 않았습니다.</p>'}</section>`;document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>stepReplay(b.dataset.decision));if($('#finishReplay'))$('#finishReplay').onclick=()=>stepReplay('finish')}
function stepReplay(action){const s=trainer.session;if(!s||s.finished)return;const reason=$('#decisionReason').value.trim();if(reason.length<5){$('#decisionError').textContent='결과를 보기 전에 판단 이유를 5자 이상 적어 주세요.';return}if(action==='buy'&&s.book.cash<.01||action==='sell'&&s.book.units<=0){$('#decisionError').textContent='이 거래에 필요한 현금 또는 보유분이 없습니다.';return}const date=s.rows[s.cursor][0];if(action==='finish'){s.decisions.push({date,action:'남은 기간 보유',reason});for(let i=s.cursor+1;i<=s.end;i++)s.curve.push([s.rows[i][0],s.book.cash+s.book.units*s.rows[i][1]]);s.cursor=s.end;}else{s.cursor++;const price=s.rows[s.cursor][1];const t=action==='hold'?{fee:0}:tradeAt(s.book,price,action,s.fee,action==='buy'?s.book.cash*.25:.25);s.decisions.push({date,action:{buy:'현금 25% 매수',sell:'보유분 25% 매도',hold:'유지'}[action],reason,execution:s.rows[s.cursor][0],fee:t.fee});s.curve.push([s.rows[s.cursor][0],s.book.cash+s.book.units*price]);}if(s.cursor===s.end){s.finished=true;if(!s.saved){recordTraining('과거 시점 훈련',s,{...statsFor(s.curve,s.initial),...s.book},s.decisions);s.saved=true}}showReplay();showTrainingHistory()}
function replayOutcome(s){const own=statsFor(s.curve,s.initial),hold=simulateHistory(s.rows,s.start,s.end,s.initial,s.fee,'hold');return `<div class="calc-result"><h3>판단 결과를 비교해 보세요</h3><p>내 수익률 <strong>${own.returnPct.toFixed(2)}%</strong> · 일괄매수 후 보유 <strong>${hold.returnPct.toFixed(2)}%</strong><br>최대 낙폭 ${own.mdd.toFixed(2)}% · 거래비용 ${money(s.book.fees)}</p><p class="note">수익이 높았다는 사실만으로 판단 과정이 좋았다고 단정하지 마세요. 당시 근거가 있었는지, 손실을 견딜 수 있었는지 기록을 돌아보세요.</p></div>`}
function showBacktest(){const r=trainer.result;const startDate=r.rows[r.start][0],endDate=r.rows[r.end][0],v=stockRows('VOO');const a=v.findIndex(x=>x[0]===startDate),b=v.findIndex(x=>x[0]===endDate);const bench=a>=0&&b>a?{name:'VOO 기준선',...simulateHistory(v,a,b,r.initial,r.fee,'hold')}:null;const results=[...r.strategies,...(bench?[bench]:[])];$('#trainingStage').innerHTML=`<section class="panel" style="margin-top:22px"><span class="tag">${r.symbol} · 실제 적용 ${startDate} ~ ${endDate}</span><h2 style="margin:12px 0">같은 돈, 다른 판단 규칙</h2>${trainingChart(results)}<div class="training-table-wrap"><table class="training-table"><thead><tr><th>전략</th><th>종료 평가액</th><th>누적 수익률</th><th>최대 낙폭</th><th>거래 / 비용</th></tr></thead><tbody>${results.map(s=>`<tr><th>${s.name}</th><td>${money(s.end)}</td><td>${s.returnPct.toFixed(2)}%</td><td>${s.mdd.toFixed(2)}%</td><td>${s.trades}회 / ${money(s.fees)}</td></tr>`).join('')}</tbody></table></div><p class="note">최대 낙폭은 가상 자산의 이전 최고점 대비 가장 크게 하락한 비율입니다. 변동성이 낮아 보이는 전략도 현금을 오래 보유해 상승을 놓칠 수 있습니다.</p><details class="research-detail" open><summary>전략이 실제로 한 일</summary><ul class="note"><li>일괄매수: 시작일 다음 거래일에 초기 자금을 모두 투입하고 보유합니다.</li><li>분할매수: 같은 초기 현금을 네 등분해 첫 체결일과 21·42·63거래일 뒤에 투입합니다. 기간이 짧으면 일부 현금이 남습니다. 추가 입금형 적립식은 아닙니다.</li><li>이동평균: 직전 거래일 종가가 그날까지 20일 평균보다 높으면 다음 종가에 전액 매수, 이하이면 다음 종가에 전량 매도합니다. 판단과 체결 사이 하루의 가격 차이가 반영됩니다.</li><li>VOO도 같은 기간·초기 자금·비용으로 비교합니다. ${r.symbol==='VOO'?'선택 종목이 VOO이므로 일괄매수와 기준선은 같습니다.':''}</li></ul></details><p class="note">기간을 바꾸면 결론도 달라집니다. 좋은 결과가 나온 구간만 선택하지 말고 상승·하락·횡보 기간을 나눠 검토하세요.</p></section>`;showTrainingHistory()}
function recordTraining(type,cfg,result,decisions){trainingLog.push({type,symbol:cfg.symbol,start:cfg.rows[cfg.start][0],end:cfg.rows[cfg.end][0],initial:cfg.initial,fee:cfg.fee,returnPct:result.returnPct,mdd:result.mdd,decisions,...(type==='백테스트'?{strategies:cfg.strategies.map(s=>({name:s.name,returnPct:s.returnPct,mdd:s.mdd,fees:s.fees}))}:{})});trainingLog=trainingLog.slice(-100);try{localStorage.setItem('longview-training-v1',JSON.stringify(trainingLog))}catch{toast('훈련 기록을 저장할 수 없습니다. 기록을 내려받아 보관하세요.')}}
function showTrainingHistory(){if(!$('#trainingHistory'))return;$('#trainingHistory').innerHTML=trainingLog.length?trainingLog.slice(-5).reverse().map(x=>`<div class="decision-entry"><strong>${esc(x.symbol)} · ${esc(x.type)}</strong><p class="note">${esc(x.start)} ~ ${esc(x.end)} · ${Number(x.returnPct).toFixed(2)}% ${x.type==='백테스트'?'(일괄매수 기준)':''} · 최대 낙폭 ${Number(x.mdd).toFixed(2)}%</p></div>`).join(''):'<p class="note">완료한 훈련이 없습니다. 최근 5개 결과가 여기에 표시됩니다.</p>'}
function exportTraining(){if(!trainingLog.length){toast('먼저 훈련이나 백테스트를 완료해 주세요.');return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({description:'LONGVIEW 학습 기록 · 수익률은 가상 결과',records:trainingLog},null,2)],{type:'application/json;charset=utf-8'}));a.download='longview-training-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
